﻿<!DOCTYPE html>
<html>

	<head>
		<meta charset="UTF-8">
		<meta http-equiv="x-ua-compatible" content="ie=edge">
		<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=0">
		<title></title>

		<script nonce="MjgzNzMzNTQxNzg0NjIyNzYyOTczNzMwODY2OTU2NjkwNTQ3NDA0" src="https://ajax.googleapis.com/ajax/libs/jquery/1.11.0/jquery.min.js"></script>
	</head>
	<style>
		body {
			font-family: Arial, Helvetica, sans-serif;
			color: #575756;
			margin: 0;
			padding: 0;
		}

		.wrapper {
			margin: auto;
			max-width: 970px;
			padding: 0 20px;
			position: relative;
		}

		.clear {
			clear: both;
			display: table;
			content: "";
		}

		.logo {
			padding: 30px 0;
			text-align: right;
		}

		.header {
			width: 100%;
			position: relative;
		}

		.header img {
			display: block;
			width: 100%;
			height: auto;
		}

		.header .header-title {
			position: absolute;
			background-color: rgba(188, 207, 0, 0.9);
			bottom: 20px;
			color: #fff;
			font-size: 24px;
			left: 0;
			padding: 15px 20px;
		}

		.header .header-title .titel-top {
			font-weight: bold;
		}

		.header .header-title .titel-bottom {
			display: block;
			margin-top: 5px;
		}

		.top {
			margin: 30px 0 50px;
		}

		.top p {
			font-size: 15px;
			line-height: 20px;
			margin-bottom: 20px;
		}

		.content {
			display: flex;
			flex-wrap: wrap;
		}

		.main {
			-webkit-box-sizing: border-box;
			-moz-box-sizing: border-box;
			box-sizing: border-box;
			width: calc(100% - 250px);
			padding-right: 40px;
			border-right: 1px solid #c2c3c3;
		}

		h1 {
			color: #b1c127;
			font-size: 28px;
			font-weight: bold;
			margin: 0 0 5px;
		}

		h2 {
			font-size: 17px;
			font-weight: bold;
			margin: 40px 0 20px;
		}

		.subtitle {
			font-size: 17px;
			margin: 0 0 40px;
		}

		ul {
			margin: 0;
			padding: 0 0 0 17px;
		}

		ul li {
			margin-bottom: 10px;
		}

		.sidebar {
			-webkit-box-sizing: border-box;
			-moz-box-sizing: border-box;
			box-sizing: border-box;
			padding-left: 40px;
			width: 250px;
			flex-shrink: 0;
		}

		.button {
			background: #b1c127;
			border: 1px solid #b1c127;
			-webkit-border-radius: 5px;
			-moz-border-radius: 5px;
			border-radius: 5px;
			color: #ffffff;
			display: block;
			font-size: 15px;
			font-weight: bold;
			margin-bottom: 40px;
			text-transform: uppercase;
			text-decoration: none;
			text-align: center;
			padding: 20px;
		}

		.button .icon-arrow {
			margin-right: 10px;
		}

		.button:hover {
			color: #e4ec99;
		}

		.button:hover .arrow {
			fill: #e4ec99;
		}

		.sidebar .title {
			font-size: 15px;
			font-weight: bold;
			margin-bottom: 10px;
		}

		.contact .contact-image {
			width: 100%;
			height: auto;
			margin-bottom: 10px;
		}

		.contact .info {
			font-size: 15px;
			line-height: 20px;
		}

		.social {
			margin-top: 40px;
			flex-basis: 100%;
		}

		.social a {
			text-decoration: none;
			display: inline-block;
			float: left;
			padding-left: 20px;
		}

		.social a:first-of-type {
			padding-left: 0;
		}

		.social a .social-icon {
			-webkit-transition: all 0.2s ease-in-out 0s;
			-moz-transition: all 0.2s ease-in-out 0s;
			-ms-transition: all 0.2s ease-in-out 0s;
			-o-transition: all 0.2s ease-in-out 0s;
			transition: all 0.2s ease-in-out 0s;
		}

		.social a:hover .social-icon {
			fill: #b1c127;
		}

		.link-list {
			margin: 40px 0 0;
			padding: 0;
			list-style: none;
		}

		.link-list li a {
			text-decoration: none;
			color: #b1c127;
			font-size: 15px;
			font-weight: bold;
		}

		.link-list li a .icon-arrow {
			margin-right: 5px;
		}

		.services {
			width: 100%;
		}

		.services h2 {
			text-align: center;
			display: block;
		}

		.service-list {
			display: flex;
			flex-wrap: wrap;
			justify-content: center;
			padding: 0;
			margin: 0 0 40px;
			list-style: none;
		}

		.service-list li {
			display: inline-block;
			margin: 0 12px 20px;
			position: relative;
			float: left;
		}

		.service-list li .service-icon {
			cursor: pointer;
			display: block;
			height: 80px;
			width: 80px;
			border: 1px solid #b1c127;
			-webkit-border-radius: 50%;
			-moz-border-radius: 50%;
			border-radius: 50%;
			position: relative;
			-webkit-transition: all 0.2s ease-in-out 0s;
			-moz-transition: all 0.2s ease-in-out 0s;
			-ms-transition: all 0.2s ease-in-out 0s;
			-o-transition: all 0.2s ease-in-out 0s;
			transition: all 0.2s ease-in-out 0s;
		}

		.service-list li .service-icon svg {
			position: absolute;
			left: 50%;
			top: 50%;
			transform: translate(-50%, -50%);
		}

		.service-list li .service-icon .icon-service {
			fill: #b1c127;
			-webkit-transition: all 0.2s ease-in-out 0s;
			-moz-transition: all 0.2s ease-in-out 0s;
			-ms-transition: all 0.2s ease-in-out 0s;
			-o-transition: all 0.2s ease-in-out 0s;
			transition: all 0.2s ease-in-out 0s;
		}

		.service-list li .tooltip {
			margin: 0;
			opacity: 0;
			position: absolute;
			top: 85px;
			left: 50%;
			text-align: center;
			width: 300px;
			-webkit-transform: translate(-50%, 0);
			-moz-transform: translate(-50%, 0);
			-ms-transform: translate(-50%, 0);
			-o-transform: translate(-50%, 0);
			transform: translate(-50%, 0);
			-webkit-transition: all 0.2s ease-in-out 0s;
			-moz-transition: all 0.2s ease-in-out 0s;
			-ms-transition: all 0.2s ease-in-out 0s;
			-o-transition: all 0.2s ease-in-out 0s;
			transition: all 0.2s ease-in-out 0s;
			z-index: 1;
			pointer-events: none;
		}

		.service-list li .tooltip.left {
			left: 0;
			text-align: left;
			-webkit-transform: translate(0, 0);
			-moz-transform: translate(0, 0);
			-ms-transform: translate(0, 0);
			-o-transform: translate(0, 0);
			transform: translate(0, 0);
		}

		.service-list li .tooltip.right {
			left: auto;
			right: 0;
			text-align: right;
			-webkit-transform: translate(0, 0);
			-moz-transform: translate(0, 0);
			-ms-transform: translate(0, 0);
			-o-transform: translate(0, 0);
			transform: translate(0, 0);
		}

		.service-list li .tooltip .tooltip-text {
			font-size: 15px;
			color: #fff;
			display: inline-block;
			background: #b1c127;
			padding: 10px 15px;
			margin: 0 auto;
		}

		.service-list li .tooltip:before {
			content: '';
			width: 0;
			height: 0;
			border-style: solid;
			border-width: 0 10px 8px 10px;
			border-color: transparent transparent #b1c127 transparent;
			position: absolute;
			top: -8px;
			left: 50%;
			-webkit-transform: translate(-50%, 0);
			-moz-transform: translate(-50%, 0);
			-ms-transform: translate(-50%, 0);
			-o-transform: translate(-50%, 0);
			transform: translate(-50%, 0);
		}

		.service-list li .tooltip.left:before {
			left: 40px;
		}

		.service-list li .tooltip.right:before {
			left: auto;
			right: 20px;
		}

		.service-list li.active .service-icon {
			background: #b1c127;
		}

		.service-list li.active .service-icon .icon-service {
			fill: #ffffff;
		}

		.service-list li.active .tooltip {
			opacity: 1;
			top: 95px;
		}

		.bubble {
			display: block;
			text-align: center;
			margin-bottom: 100px;
			position: relative;
		}

		.bubble p {
			display: inline-block;
			background: #e4ec99;
			margin: 0;
			padding: 30px 35px;
			border-radius: 20px;
			font-size: 24px;
		}

		.bubble:after {
			content: '';
			width: 0;
			height: 0;
			border-style: solid;
			border-width: 23px 26px 0 0;
			border-color: #e4ec99 transparent transparent transparent;
			position: absolute;
			bottom: -23px;
			left: 25%;
		}

		@media screen and (max-width: 969px) {
			.header .header-title {
				bottom: 0;
				font-size: 18px;
			}

			.main {
				padding-right: 20px;
				width: calc(100% - 230px);
			}

			.sidebar {
				width: 230px;
				padding-left: 20px;
			}
		}

		@media screen and (max-width: 767px) {
			.header .header-title {
				position: relative;
			}

			.logo img {
				height: 44px;
				width: auto;
			}

			.top {
				margin: 30px 0 40px;
			}

			h1 {
				font-size: 24px;
				margin-bottom: 10px;
			}

			h2 {
				font-size: 15px;
				margin: 30px 0 20px;
			}

			.subtitle {
				margin-bottom: 30px;
			}

			.main {
				order: 1;
				width: 100%;
				padding: 0;
				border-right: 0;
			}

			.sidebar {
				text-align: center;
				width: 100%;
				padding: 0;
				order: 3;
			}

			.social {
				display: flex;
				flex-wrap: wrap;
				justify-content: center;
			}

			.social .title {
				flex-basis: 100%;
			}

			.services {
				order: 2;
			}

			.link-list {
				display: flex;
				flex-wrap: wrap;
				justify-content: space-around;
			}

			.link-list li a {
				white-space: nowrap;
			}

			.bubble {
				margin-top: 30px;
			}

			.bubble p {
				font-size: 18px;
				padding: 20px;
			}
		}

		@media print {
			body {
				margin: 0;
				padding: 0;
				-webkit-print-color-adjust: exact;
			}

			.wrapper {
				padding: 0;
				margin: 0;
			}

			.header .header-title {
				background-color: rgba(188, 207, 0, 0.9) !important;
				-webkit-print-color-adjust: exact;
			}

			.service-list li.active .service-icon {
				background: #b1c127 !important;
				-webkit-print-color-adjust: exact;
			}

			.service-list li.active .service-icon .icon-service {
				fill: #ffffff !important;
			}

			.service-list li .tooltip .tooltip-text {
				background: #b1c127 !important;
				-webkit-print-color-adjust: exact;
			}

			.button {
				display: none;
			}

			.link-list {
				display: none;
			}

			.bubble p {
				background-color: #e4ec99 !important;
				-webkit-print-color-adjust: exact;
			}
		}
	</style>

